import assert from 'node:assert';
import { describe, it } from 'node:test';
import { lineTotal, invoiceTotals } from '../src/totals.js';
import { createInvoice, addLine, applyVoucher } from '../src/invoices.js';
import { roundCents } from '../src/money.js';

describe('lineTotal', () => {
  it('calculates qty times unitPrice', () => {
    const line = { qty: 5, unitPrice: 8500 };
    assert.equal(lineTotal(line), 42500);
  });

  it('handles single unit', () => {
    const line = { qty: 1, unitPrice: 1000 };
    assert.equal(lineTotal(line), 1000);
  });

  it('handles large quantities', () => {
    const line = { qty: 100, unitPrice: 5000 };
    assert.equal(lineTotal(line), 500000);
  });
});

describe('invoiceTotals', () => {
  it('calculates subtotal and total for a single line', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 42500);
  });

  it('calculates subtotal and total for multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, vatRate: 0 },
        { qty: 3, unitPrice: 9500, vatRate: 0 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500 + 28500);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 42500 + 28500);
  });

  it('handles empty invoice', () => {
    const invoice = { lines: [] };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 0);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 0);
  });

  it('works with invoice from createInvoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const expectedSubtotal = 5 * 8500 + 3 * 9500;
    const expectedVat = roundCents(5 * 8500 * 0.21) + roundCents(3 * 9500 * 0.21);
    assert.equal(totals.subtotal, expectedSubtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, expectedVat);
    assert.equal(totals.total, expectedSubtotal + expectedVat);
  });

  it('calculates discount for a single line with 10% discount', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 4250);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 38250);
  });

  it('calculates discount with decimal percentage', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 12.5, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 5312.5);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 37187.5);
  });

  it('calculates total discount across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 0 },
        { qty: 3, unitPrice: 9500, discountPercent: 20, vatRate: 0 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500 + 28500);
    assert.equal(totals.discount, 4250 + 5700);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 42500 + 28500 - 4250 - 5700);
  });

  it('clamps total at 0 when discount exceeds subtotal', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 100, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 42500);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 0);
  });

  it('handles mixed discounted and non-discounted lines', () => {
    const invoice = {
      lines: [
        { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
        { qty: 5, unitPrice: 2000, discountPercent: 50, vatRate: 0 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 9000 + 10000);
    assert.equal(totals.discount, 5000);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 14000);
  });

  it('works with invoice from createInvoice with discounts', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
        { sku: 'DEV-HOUR', qty: 3, discountPercent: 5 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 5 * 8500 + 3 * 9500;
    const discount = (5 * 8500) * 0.1 + (3 * 9500) * 0.05;
    const vat1 = roundCents((5 * 8500 - (5 * 8500) * 0.1) * 0.21);
    const vat2 = roundCents((3 * 9500 - (3 * 9500) * 0.05) * 0.21);
    const vat = vat1 + vat2;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - discount + vat);
  });

  it('calculates totals with tier discounts applied', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 5 * 8500 + 3 * 9500;
    const discount = (5 * 8500) * 0.05 + (3 * 9500) * 0.05;
    const afterDiscount1 = 5 * 8500 - (5 * 8500) * 0.05;
    const afterDiscount2 = 3 * 9500 - (3 * 9500) * 0.05;
    const vat = roundCents(afterDiscount1 * 0.21) + roundCents(afterDiscount2 * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - discount + vat);
  });

  it('applies correct discount when mixing tier and explicit discounts', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-003',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 10 },
        { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 10 * 8500 + 5 * 9500;
    const tierDiscount = (10 * 8500) * 0.025;
    const explicitDiscount = 0;
    const discount = tierDiscount + explicitDiscount;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
  });

  it('calculates VAT on line after discount', () => {
    const invoice = {
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 100000;
    const discount = 10000;
    const afterDiscount = 90000;
    const vat = roundCents(90000 * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - discount + vat);
  });

  it('calculates VAT with 21% rate', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000;
    const vat = roundCents(10000 * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal + vat);
  });

  it('calculates VAT with 9% rate', () => {
    const invoice = {
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 9 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 100000;
    const vat = roundCents(100000 * 0.09);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal + vat);
  });

  it('calculates VAT with 0% rate', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 10000);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 10000);
  });

  it('sums VAT across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
        { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000 + 10000;
    const vat1 = roundCents(10000 * 0.21);
    const vat2 = roundCents(10000 * 0.09);
    const totalVat = vat1 + vat2;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, totalVat);
    assert.equal(totals.total, subtotal + totalVat);
  });

  it('rounds VAT per line before summing', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
        { qty: 3, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const vat1 = roundCents(3000 * 0.21);
    const vat2 = roundCents(3000 * 0.21);
    const expectedVat = vat1 + vat2;
    assert.equal(totals.vat, expectedVat);
  });

  it('calculates VAT on amount after discount and tier discount', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 100 }],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 100 * 8500;
    const tierDiscount = subtotal * 0.05;
    const afterDiscount = subtotal - tierDiscount;
    const vat = roundCents(afterDiscount * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, tierDiscount);
    assert.equal(totals.vat, vat);
  });

  it('includes voucher in total calculation', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const totalsWithoutVoucher = invoiceTotals(invoiceResult.value);

    const voucherResult = applyVoucher(invoiceResult.value, { code: 'WELCOME10', amount: 1000 });
    assert(voucherResult.ok);

    const totalsWithVoucher = invoiceTotals(voucherResult.value);

    assert.equal(totalsWithVoucher.voucher, 1000);
    assert.equal(totalsWithVoucher.total, totalsWithoutVoucher.total - 1000);
  });

  it('returns 0 voucher for invoice without voucher', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);

    assert.equal(totals.voucher, 0);
  });

  it('clamps total at 0 when voucher exceeds subtotal + vat', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(invoiceResult.ok);
    const totalsWithoutVoucher = invoiceTotals(invoiceResult.value);
    const largeVoucher = totalsWithoutVoucher.total + 10000;

    const voucherResult = applyVoucher(invoiceResult.value, { code: 'HUGE', amount: largeVoucher });
    assert(voucherResult.ok);

    const totals = invoiceTotals(voucherResult.value);
    assert.equal(totals.total, 0);
  });

  it('calculates correct total with voucher applied', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    });

    assert(invoiceResult.ok);
    const totalsBase = invoiceTotals(invoiceResult.value);

    const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE50', amount: 5000 });
    assert(voucherResult.ok);

    const totalsWithVoucher = invoiceTotals(voucherResult.value);
    const expectedTotal = Math.max(0, totalsBase.subtotal - totalsBase.discount + totalsBase.vat - 5000);

    assert.equal(totalsWithVoucher.total, expectedTotal);
  });

  it('applies bulk discount for 10 or more units', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000;
    const bulkDiscount = subtotal * 0.025;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, bulkDiscount);
    assert.equal(totals.total, subtotal - bulkDiscount);
  });

  it('does not apply bulk discount for 9 units', () => {
    const invoice = {
      lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 9000;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.total, subtotal);
  });

  it('applies bulk discount after line discount', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000;
    const lineDiscount = 1000;
    const afterLineDiscount = 9000;
    const bulkDiscount = afterLineDiscount * 0.025;
    const expectedDiscount = lineDiscount + bulkDiscount;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, expectedDiscount);
    assert.equal(totals.total, subtotal - expectedDiscount);
  });

  it('applies bulk discount with tier discount', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 10 }],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 10 * 8500;
    const tierDiscount = subtotal * 0.05;
    const afterTierDiscount = subtotal - tierDiscount;
    const bulkDiscount = afterTierDiscount * 0.025;
    const expectedDiscount = tierDiscount + bulkDiscount;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, expectedDiscount);
  });

  it('calculates VAT on amount after bulk discount', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000;
    const bulkDiscount = subtotal * 0.025;
    const afterBulkDiscount = subtotal - bulkDiscount;
    const vat = roundCents(afterBulkDiscount * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, bulkDiscount);
    assert.equal(totals.vat, vat);
  });

  it('applies bulk discount with both line and VAT', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000;
    const lineDiscount = 1000;
    const afterLineDiscount = 9000;
    const bulkDiscount = afterLineDiscount * 0.025;
    const afterBulkDiscount = afterLineDiscount - bulkDiscount;
    const vat = roundCents(afterBulkDiscount * 0.21);
    const expectedDiscount = lineDiscount + bulkDiscount;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, expectedDiscount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - expectedDiscount + vat);
  });

  it('applies bulk discount on multiple lines independently', () => {
    const invoice = {
      lines: [
        { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
        { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 15000;
    const bulkDiscount1 = 10000 * 0.025;
    const bulkDiscount2 = 0;
    const expectedDiscount = bulkDiscount1 + bulkDiscount2;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, expectedDiscount);
  });

  it('applies bulk discount at quantity boundary (exactly 10)', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000;
    const expectedBulkDiscount = 250;
    assert.equal(totals.discount, expectedBulkDiscount);
  });

  it('bulk discount with 21 units', () => {
    const invoice = {
      lines: [{ qty: 21, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 21000;
    const bulkDiscount = subtotal * 0.025;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, bulkDiscount);
  });

  it('bulk discount with various VAT rates', () => {
    const invoice = {
      lines: [
        { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
        { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 20000;
    const bulkDiscount1 = 10000 * 0.025;
    const bulkDiscount2 = 10000 * 0.025;
    const expectedDiscount = bulkDiscount1 + bulkDiscount2;
    const vat1 = roundCents((10000 - bulkDiscount1) * 0.21);
    const vat2 = roundCents((10000 - bulkDiscount2) * 0.09);
    const expectedVat = vat1 + vat2;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, expectedDiscount);
    assert.equal(totals.vat, expectedVat);
  });

  it('bulk discount with explicit discount and tier discount', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 5 }],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 10 * 8500;
    const tierDiscount = subtotal * 0.05;
    const explicitDiscount = subtotal * 0.05;
    const lineDiscount = tierDiscount + explicitDiscount;
    const afterLineDiscount = subtotal - lineDiscount;
    const bulkDiscount = afterLineDiscount * 0.025;
    const expectedDiscount = lineDiscount + bulkDiscount;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, expectedDiscount);
  });
});

