import assert from 'node:assert';
import { describe, it } from 'node:test';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';
import { roundCents } from '../src/money.js';

describe('createInvoice', () => {
  it('creates a draft invoice with valid input', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(result.ok);
    assert.equal(result.value.customerId, 'C-001');
    assert.equal(result.value.issueDate, '2025-12-15');
    assert.equal(result.value.status, 'draft');
    assert.equal(result.value.lines.length, 2);
    assert.equal(result.value.lines[0].sku, 'DES-HOUR');
    assert.equal(result.value.lines[0].name, 'Design work (hour)');
    assert.equal(result.value.lines[0].qty, 5);
    assert.equal(result.value.lines[0].unitPrice, 8500);
    assert.equal(result.value.lines[0].vatRate, 21);
    assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(result.value.lines[1].name, 'Development (hour)');
    assert.equal(result.value.lines[1].qty, 3);
  });

  it('normalizes lowercase customer ID', () => {
    const result = createInvoice({
      customerId: 'c-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.customerId, 'C-001');
  });

  it('normalizes mixed case customer ID', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.customerId, 'C-001');
  });

  it('normalizes customer ID with leading/trailing spaces', () => {
    const result = createInvoice({
      customerId: ' c-001 ',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.customerId, 'C-001');
  });

  it('accepts mixed case and spaces in customer ID', () => {
    const result = createInvoice({
      customerId: ' C-002 ',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.customerId, 'C-002');
  });

  it('returns CUSTOMER_NOT_FOUND for unknown customer', () => {
    const result = createInvoice({
      customerId: 'unknown-cust',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
  });

  it('returns DATE_INVALID for invalid date format', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '15-12-2025',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns DATE_INVALID for non-existent date', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns DATE_INVALID for invalid format without dashes', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '20251215',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns NO_LINES for empty lines array', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [],
    });

    assert(!result.ok);
    assert.equal(result.error, 'NO_LINES');
  });

  it('returns NO_LINES for missing lines', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: undefined,
    });

    assert(!result.ok);
    assert.equal(result.error, 'NO_LINES');
  });

  it('returns QTY_INVALID for zero quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for negative quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for fractional quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns UNKNOWN_SKU for invalid SKU', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'INVALID', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'UNKNOWN_SKU');
  });

  it('does not mutate input lines', () => {
    const inputLines = [{ sku: 'DES-HOUR', qty: 5 }];
    const linesCopy = JSON.parse(JSON.stringify(inputLines));

    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: inputLines,
    });

    assert.deepEqual(inputLines, linesCopy);
  });

  it('accepts discount on a line', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 10);
  });

  it('accepts decimal discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 12.5);
  });

  it('applies tier discount when not explicitly provided', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 5);
  });

  it('returns DISCOUNT_INVALID for negative discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  it('returns DISCOUNT_INVALID for discount over 100', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 101 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  it('returns DISCOUNT_INVALID for non-numeric discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  it('accepts 0 and 100 as valid discount bounds', () => {
    const result1 = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    });

    assert(result1.ok);
    assert.equal(result1.value.lines[0].discountPercent, 0);

    const result2 = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DEV-HOUR', qty: 3, discountPercent: 100 }],
    });

    assert(result2.ok);
    assert.equal(result2.value.lines[0].discountPercent, 100);
  });

  it('applies gold tier discount when no explicit discount provided', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 5);
  });

  it('applies silver tier discount when no explicit discount provided', () => {
    const result = createInvoice({
      customerId: 'C-003',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 2.5);
