describe('removeLine', () => {
  it('removes a line from an invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

