import { roundCents } from './money.js';

/**
 * Calculate the total amount for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineSubtotal = lineTotal(line);
    const lineDiscount = lineSubtotal * (line.discountPercent ?? 0) / 100;
    const lineAfterDiscount = Math.max(0, lineSubtotal - lineDiscount);
    const bulkDiscount = line.qty >= 10 ? lineAfterDiscount * 0.025 : 0;
    return sum + Math.max(0, lineDiscount + bulkDiscount);
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const lineSubtotal = lineTotal(line);
    const lineDiscount = lineSubtotal * (line.discountPercent ?? 0) / 100;
    const lineAfterDiscount = Math.max(0, lineSubtotal - lineDiscount);
    const bulkDiscount = line.qty >= 10 ? lineAfterDiscount * 0.025 : 0;
    const lineAfterAllDiscounts = Math.max(0, lineAfterDiscount - bulkDiscount);
    const lineVat = roundCents(lineAfterAllDiscounts * (line.vatRate ?? 0) / 100);
    return sum + Math.max(0, lineVat);
  }, 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}
